    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
    }







    @Test
    public void testNoGenericsInBaseType() {
        // Case: baseType.getBindings().isEmpty()
        // Even if it's a container, if it has no bindings, it hits the first shortcut
        JavaType baseType = typeFactory.constructCollectionType(List.class, String.class);
        // Note: constructCollectionType usually creates bindings. 
