 * Aiming for high branch and line coverage.
 */
public class TypeFactory_constructSpecializedType_TriageGen0Test {

    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
    }

















    @Test
    public void testFullResolutionFallback() {
        // Case: Fallback to refine() / _bindingsForSubtype
        // This happens when it's a container but NOT one of the shortcuts, 
        // or has generics and is not a shortcut.

        // Using a Map but a subclass that isn't in the shortcut list (e.g., a custom Map)
        class CustomMap extends HashMap<String, String> {}

        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, Integer.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, CustomMap.class);

        assertEquals(CustomMap.class, result.getRawClass());
        assertEquals(String.class, result.getKeyType().getRawClass());
        assertEquals(Integer.class, result.getContentType().getRawClass());
    }


}

