        typeFactory = TypeFactory.defaultInstance();
    }



















    @Test
    public void testInterfaceRefinement() {
        // Case: baseType.isInterface() is true
        JavaType baseType = typeFactory.constructType(Map.class); // Map is interface
        // Force bindings
        JavaType parameterizedBase = typeFactory.constructMapType(Map.class, String.class, Integer.class);

        // Use a concrete class that implements Map
        JavaType result = typeFactory.constructSpecializedType(parameterizedBase, HashMap.class);

        assertEquals(HashMap.class, result.getRawClass());
        assertEquals(String.class, result.getKeyType().getRawClass());
        assertEquals(Integer.class, result.getContentType().getRawClass());
    }
